#!/bin/bash
# SPDX-License-Identifier: GPL-3.0-or-later
# commit-message-check.sh: fail when a commit message carries an attribution line, when its author or committer
# name or email matches the identity pattern, or when a merge subject names a branch under claude/.
#
#   commit-message-check.sh <range>          every commit in the range (e.g. origin/main..HEAD)
#   commit-message-check.sh --msg-file FILE  one message (the commit-msg hook; # lines are git comments, skipped)
#   commit-message-check.sh --text-file FILE any text, every line judged (PR titles and bodies)
#   commit-message-check.sh --selftest       fixtures plus a sabotage run
#
# Exit 0 clean, 1 a hit (each commit and offending line is named), 2 a range, file or pattern list that cannot be read
# (any crash is 2). Callers refuse on 2: a checker that cannot judge is never a pass.
# The patterns are commit-message-patterns.json beside this script, the same list the ops sweep strips
# issue and PR text with, and the one list every door reads: merge-pr.sh, integrate-check.sh, pr-from-devel.sh
# (ops/tools/tests/commit-message-one-list.t.sh refuses a second list). COMMIT_MESSAGE_PATTERNS names another JSON (self-tests). Repos that cannot see the ops tree carry a copy of both files.
set -euo pipefail
export COMMIT_MESSAGE_CHECK_SELF="${BASH_SOURCE[0]}"
exec python3 -I - "$@" <<'PY'
import json, os, re, subprocess, sys

here = os.path.dirname(os.path.realpath(os.environ["COMMIT_MESSAGE_CHECK_SELF"]))
pfile = os.environ.get("COMMIT_MESSAGE_PATTERNS") or os.path.join(here, "commit-message-patterns.json")


def load():
    with open(pfile, encoding="utf-8") as f:
        return [(m["name"], re.compile(m["pattern"], re.I | re.M)) for m in json.load(f)["markers"]]


def load_ident():
    with open(pfile, encoding="utf-8") as f:
        j = json.load(f)
    return re.compile(j["identity"]["pattern"], re.I), re.compile(j["merge-branch"]["pattern"], re.I)


def ident_hits(name, email, subject, parents, ident, branch):
    """Who made the commit, and which branch a merge names; the message text is judged by hits()."""
    out = []
    for who, v in (("author", name[0] + " <" + email[0] + ">"), ("committer", name[1] + " <" + email[1] + ">")):
        if ident.search(v):
            out.append((0, who, v))
    if subject.startswith("Merge") and branch.search(subject):
        out.append((1, "merge-branch", subject))
    return out


def commit_ident_hits(sha, ident, branch):
    f = git("log", "-1", "--format=%an%x00%ae%x00%cn%x00%ce%x00%P%x00%s", sha).rstrip("\n").split("\0")
    return ident_hits((f[0], f[2]), (f[1], f[3]), f[5], len(f[4].split()), ident, branch)


def hits(text, markers):
    out = []
    for n, line in enumerate(text.splitlines(), 1):
        for name, rx in markers:
            if rx.search(line):
                out.append((n, name, line.strip()))
    return out


def report(label, text, markers):
    h = hits(text, markers)
    for n, name, line in h:
        print(f"{label}: line {n} [{name}]: {line}")
    return len(h)


def git(*a):
    p = subprocess.run(["git", *a], capture_output=True, text=True)
    if p.returncode:
        print(f"commit-message-check: git {' '.join(a[:3])}: {p.stderr.strip()}", file=sys.stderr)
        sys.exit(2)
    return p.stdout


def selftest():
    fx = {
        "co-authored\x2dby": "Fix x\n\nCo-Authored\x2dBy: Claude Opus <noreply@anthropi\x63.com>\n",
        "claude-session": "Fix x\n\nClaude-Session: https://claude\x2eai/code/session_01\n",
        "generated-footer": "Fix x\n\n\U0001F916 Generated with [Claude Code](https://claude.com/claude-code)\n",
        "claude\x2eai/code": "Fix x\n\nsee https://claude\x2eai/code/session_9\n",
        # the shapes the omx-dsp#155 review saw pass
        "assisted-by": "Fix x\n\nAssisted-by: Claude\n",
        "made-with": "Fix x\n\nMade with Claude Code\n",
        "generated-with-claude": "Fix x\n\nGenerated with Claude\n",
        "generated-by-trailer": "Fix x\n\nGenerated-by: Claude\n",
        "co-author-model": "Fix x\n\nCo-authored\x2dby: Opus 5.5 <x@example.invalid>\n",
        "co-author-github-copilot": "Fix x\n\nCo-authored\x2dby: GitHub Copilot <copilot@github.com>\n",
    }
    clean = ("Fix x\n\nGenerated by the build; mentions .claude/ and a Co-Authored\x2dBy: Pau line.\n"
             "Assisted-by: Pau Aliagas\nMade with care; generated with tools/rules-index-gen.sh\n"
             "A review quoted 'Assisted-by: Claude' and 'Co-authored\x2dby: Opus 5.5 <x>' as shapes that passed.\n")
    def run(markers):
        bad = [k for k, v in fx.items() if not hits(v, markers)]
        if hits(clean, markers):
            bad.append("clean-flagged")
        return bad
    # identity fixtures: (author name, email, committer name, email, parents, subject) -> expected hit
    ident, branch = load_ident()
    nm, em, cl = "Cla" + "ude", "noreply@anthropi" + "\x63.com", "cla" + "ude"
    ifx = [
        ("author", ((nm, "Pau"), (em, "x@example.invalid"), "fix x", 1), True),
        ("committer", (("Pau", nm), ("x@example.invalid", em), "fix x", 1), True),
        ("merge-branch", (("GitHub", "GitHub"), ("noreply@github.com",) * 2, f"Merge pull request #1 from FreeMixer/{cl}/a", 2), True),
        ("ordinary", (("Pau Aliagas", "Pau Aliagas"), ("linuxnow@gmail.com", "commits@openmixer.org"), "fix x", 1), False),
        ("github-merge", (("GitHub", "GitHub"), ("noreply@github.com",) * 2, "Merge pull request #1 from FreeMixer/fix/a", 2), False),
    ]
    def irun(i, b):
        return [k for k, a, want in ifx if bool(ident_hits(a[0], a[1], a[2], a[3], i, b)) != want]
    ibad = irun(ident, branch)
    print("selftest identity:", "GREEN" if not ibad else f"RED {ibad}")
    never = re.compile(r"(?!)")
    isab = irun(never, never)
    print("sabotage (the identity and merge-branch patterns removed):",
          "RED as expected" if isab else "still GREEN: blind")
    m = load()
    first = run(m)
    print("selftest:", "GREEN" if not first else f"RED {first}")
    sab = run([x for x in m if x[0] not in ("co-authored\x2dby", "ai-co-author", "anthropi\x63-noreply", "claude-session")])
    print("sabotage (the co-author, email and session patterns removed):", "RED as expected" if sab else "still GREEN: blind")
    # each #152 shape is seen by a pattern of its own family, not by luck
    new = ["assisted-by", "made-with", "generated-with-claude", "generated-by-trailer", "co-author-model", "co-author-github-copilot"]
    sab2 = run([x for x in m if x[0] not in ("ai-assisted-by", "generated-footer", "ai-co-author-model")])
    blind = [k for k in new if k not in sab2]
    print("sabotage (the assisted-by, generated and model co-author patterns removed):",
          "RED as expected" if not blind else f"still GREEN for {blind}: blind")
    return 0 if not first and sab and not blind and not ibad and isab else 1


def main(a):
    if a == ["--selftest"]:
        return selftest()
    markers = load()
    if len(a) == 2 and a[0] == "--msg-file":
        try:
            text = open(a[1], encoding="utf-8", errors="replace").read()
        except OSError as e:
            print(f"commit-message-check: {e}", file=sys.stderr)
            return 2
        # lines git adds as comments are not part of the message
        text = "\n".join(l for l in text.splitlines() if not l.startswith("#"))
        return 1 if report("commit message", text, markers) else 0
    if len(a) == 2 and a[0] == "--text-file":
        try:
            text = open(a[1], encoding="utf-8", errors="replace").read()
        except OSError as e:
            print(f"commit-message-check: {e}", file=sys.stderr)
            return 2
        return 1 if report("text", text, markers) else 0
    if len(a) == 1 and not a[0].startswith("-"):
        shas = git("rev-list", a[0]).split()
        bad = 0
        ident, branch = load_ident()
        for sha in shas:
            bad += report(sha[:12], git("log", "-1", "--format=%B", sha), markers)
            for _, name, line in commit_ident_hits(sha, ident, branch):
                print(f"{sha[:12]}: [{name}]: {line}")
                bad += 1
        print(f"commit-message-check: {len(shas)} commits, {bad} offending lines")
        return 1 if bad else 0
    print(__doc__ if False else "usage: commit-message-check.sh <range> | --msg-file FILE | --text-file FILE | --selftest", file=sys.stderr)
    return 2


try:
    rc = main(sys.argv[1:])
except Exception as e:  # a bad or missing pattern file, a decode error: unreadable, never "a hit"
    print(f"commit-message-check: {type(e).__name__}: {e}", file=sys.stderr)
    rc = 2
sys.exit(rc)
PY
